-- Huong dan + MET cho 9 bai mau cu va them 29 bai moi (id 110-138) (noi dung mau; MET la gia tri uoc luong).
UPDATE exercises SET met = 2.8, steps = 'Đứng thẳng, mắt nhìn phía trước, vai thả lỏng.\nBước với tốc độ vừa phải, vẫn nói chuyện được.\nĐánh tay nhẹ theo nhịp bước, đặt gót rồi lăn sang mũi bàn chân.\nGiảm tốc độ dần trong 1-2 phút cuối rồi dừng.', media_urls = '/exercise-images/Walking_Treadmill/0.jpg\n/exercise-images/Walking_Treadmill/1.jpg', tips = 'Mang giày êm, chọn đường bằng phẳng.', description = 'Đi bộ với tốc độ thoải mái (ngoài trời hoặc trên máy chạy bộ), phù hợp khi mệt hoặc ít thời gian.' WHERE id = 1;
UPDATE exercises SET met = 2.3, steps = 'Đứng thẳng, hai chân rộng bằng vai.\nĐan hai tay, đưa lên cao qua đầu, hít vào và vươn người lên.\nGiữ 20-30 giây, thở đều rồi thả tay xuống.\nNghiêng nhẹ sang hai bên, mỗi bên giữ 20 giây.', media_urls = '/exercise-images/Overhead_Stretch/0.jpg\n/exercise-images/Overhead_Stretch/1.jpg', tips = 'Không nín thở, giãn đến mức căng nhẹ, không đau.' WHERE id = 2;
UPDATE exercises SET met = 2.0, steps = 'Đứng thẳng, dang hai tay ngang vai.\nXoay tay theo vòng nhỏ về phía trước 10 lần.\nĐổi chiều xoay về phía sau 10 lần.\nTăng dần vòng xoay lớn hơn nếu thấy thoải mái.', media_urls = '/exercise-images/Arm_Circles/0.jpg\n/exercise-images/Arm_Circles/1.jpg', tips = 'Giữ vai thả lỏng, không nhún vai.' WHERE id = 3;
UPDATE exercises SET met = 3.8, steps = 'Đứng chân rộng bằng vai, mũi chân hơi hướng ra ngoài.\nĐẩy hông ra sau và hạ người như ngồi xuống ghế.\nGiữ lưng thẳng, đầu gối cùng hướng mũi chân, đùi song song sàn thì dừng.\nĐạp gót chân đứng lên, siết mông ở cuối động tác.', media_urls = '/exercise-images/Bodyweight_Squat/0.jpg\n/exercise-images/Bodyweight_Squat/1.jpg', tips = '3 hiệp x 10-15 lần, nghỉ 45 giây giữa các hiệp.' WHERE id = 4;
UPDATE exercises SET met = 3.8, steps = 'Chống tay rộng hơn vai một chút, thân người thẳng từ đầu đến gót.\nHạ ngực xuống gần sàn, khuỷu tay chếch khoảng 45 độ so với thân.\nĐẩy người lên về vị trí ban đầu, không võng lưng.\nNếu còn nặng, hạ gối xuống sàn và giữ thân thẳng từ đầu đến gối.', media_urls = '/exercise-images/Pushups/0.jpg\n/exercise-images/Pushups/1.jpg', tips = '3 hiệp x 6-12 lần.' WHERE id = 5;
UPDATE exercises SET met = 3.0, steps = 'Chống khuỷu tay dưới vai, hai chân duỗi thẳng, chạm mũi chân.\nSiết bụng và mông để thân thẳng từ đầu đến gót.\nGiữ yên tư thế, thở đều, không nín thở.\nNghỉ khi hông bắt đầu võng xuống rồi lặp lại.', media_urls = '/exercise-images/Plank/0.jpg\n/exercise-images/Plank/1.jpg', tips = '3 hiệp x 20-40 giây.' WHERE id = 6;
UPDATE exercises SET met = 6.0, steps = 'Khởi động bằng đi bộ nhẹ 3 phút.\nTăng dần lên đi bộ nhanh hoặc chạy nhẹ, giữ nhịp đều.\nThân người hơi nghiêng về phía trước, bước ngắn, tiếp đất nhẹ.\nGiảm tốc độ trong 2-3 phút cuối rồi giãn cơ nhẹ.', media_urls = '/exercise-images/Trail_Running_Walking/0.jpg\n/exercise-images/Trail_Running_Walking/1.jpg', tips = 'Nếu hụt hơi, giảm tốc độ xuống mức nói chuyện được.' WHERE id = 7;
UPDATE exercises SET met = 6.5, steps = 'Đứng thẳng, hai chân rộng bằng hông.\nNâng gối cao luân phiên như chạy tại chỗ, đánh tay đối nghịch.\nĐạp nhẹ lên mũi chân, giữ thân người thẳng.\nLàm 40 giây, nghỉ 20 giây, lặp lại các hiệp.', media_urls = '/exercise-images/Fast_Skipping/0.jpg\n/exercise-images/Fast_Skipping/1.jpg', tips = 'Giảm xuống bước đi tại chỗ nếu thấy mệt.' WHERE id = 8;
UPDATE exercises SET met = 2.5, steps = 'Quỳ gối trên thảm, hai mũi chân chạm nhau, gối mở rộng bằng hông.\nNgồi lùi mông về phía gót chân, vươn hai tay về trước.\nThả trán xuống thảm, thở chậm 5-8 nhịp.\nTừ từ chống tay ngồi dậy.', media_urls = '/exercise-images/Childs_Pose/0.jpg\n/exercise-images/Childs_Pose/1.jpg', tips = 'Có thể kê gối dưới ngực nếu thấy căng.' WHERE id = 9;


