INSERT INTO exercises (id, name, description, duration_min, duration_max, difficulty, intensity, equipment, location, muscle_group, goal, energy_requirement, recovery_suitable, instructions, media_url, active, met, steps, media_urls, tips) VALUES
(110, 'Giãn lưng mèo', 'Vòng lưng lên xuống nhẹ nhàng để làm mềm cột sống.', 5, 10, 1, 'LOW', 'NONE', 'HOME', 'back', 'RECOVERY', 1, 1, NULL, NULL, 1, 2.3, 'Quỳ bốn điểm, tay dưới vai, gối dưới hông.\nHít vào, hạ bụng xuống, ngẩng đầu nhìn lên nhẹ.\nThở ra, cong lưng lên trần nhà, cúi đầu.\nLặp lại chậm 8-10 nhịp.', '/exercise-images/Cat_Stretch/0.jpg\n/exercise-images/Cat_Stretch/1.jpg', 'Di chuyển chậm theo nhịp thở.'),
(111, 'Ôm gối vào ngực', 'Giãn nhẹ lưng dưới và hông khi nằm.', 3, 8, 1, 'LOW', 'NONE', 'HOME', 'lower_back', 'RECOVERY', 1, 1, NULL, NULL, 1, 2.0, 'Nằm ngửa, hai chân co.\nDùng hai tay ôm gối kéo về phía ngực.\nGiữ 20-30 giây, thở đều.\nThả chân ra và lặp lại 2-3 lần.', '/exercise-images/Hug_Knees_To_Chest/0.jpg\n/exercise-images/Hug_Knees_To_Chest/1.jpg', 'Giữ đầu và vai thả lỏng trên sàn.'),
(112, 'Giãn cổ nghiêng bên', 'Giãn cơ cổ và vai sau nhiều giờ ngồi học.', 3, 6, 1, 'LOW', 'NONE', 'ANY', 'neck', 'RECOVERY', 1, 1, NULL, NULL, 1, 2.0, 'Ngồi hoặc đứng thẳng, vai thả lỏng.\nNghiêng đầu sang một bên, tai gần vai.\nCó thể đặt nhẹ tay cùng bên lên đầu, không kéo mạnh.\nGiữ 20-30 giây rồi đổi bên.', '/exercise-images/Side_Neck_Stretch/0.jpg\n/exercise-images/Side_Neck_Stretch/1.jpg', 'Không nhún vai lên, không kéo mạnh.'),
(113, 'Xoay vai', 'Làm ấm khớp vai bằng vòng xoay nhẹ.', 3, 6, 1, 'LOW', 'NONE', 'ANY', 'shoulders', 'RECOVERY', 1, 1, NULL, NULL, 1, 2.0, 'Đứng hoặc ngồi thẳng, hai tay thả lỏng.\nNhún vai lên rồi xoay ra sau thành vòng tròn lớn, 10 lần.\nĐổi chiều xoay về phía trước, 10 lần.', '/exercise-images/Shoulder_Circles/0.jpg\n/exercise-images/Shoulder_Circles/1.jpg', 'Xoay chậm và đều.'),
(114, 'Xoay cổ chân', 'Làm mềm cổ chân, hữu ích sau khi ngồi lâu.', 3, 6, 1, 'LOW', 'NONE', 'ANY', 'ankles', 'RECOVERY', 1, 1, NULL, NULL, 1, 2.0, 'Ngồi trên ghế, nhấc một chân khỏi sàn.\nXoay bàn chân theo vòng tròn 10 lần theo chiều kim đồng hồ.\nĐổi chiều 10 lần, rồi đổi chân.', '/exercise-images/Ankle_Circles/0.jpg\n/exercise-images/Ankle_Circles/1.jpg', 'Giữ cẳng chân đứng yên, chỉ xoay cổ chân.'),
(115, 'Xoay hông đứng', 'Mở khớp hông bằng các vòng xoay chậm.', 4, 8, 1, 'LOW', 'NONE', 'HOME', 'hips', 'RECOVERY', 1, 1, NULL, NULL, 1, 2.3, 'Đứng thẳng, tay chống hông, chân rộng bằng vai.\nXoay hông theo vòng tròn lớn, 10 lần.\nĐổi chiều xoay 10 lần.', '/exercise-images/Standing_Hip_Circles/0.jpg\n/exercise-images/Standing_Hip_Circles/1.jpg', 'Giữ thân trên ổn định, đầu gối hơi mềm.'),
(116, 'Giãn gân kheo ngồi', 'Giãn mặt sau đùi khi ngồi trên sàn.', 4, 8, 1, 'LOW', 'NONE', 'HOME', 'hamstrings', 'RECOVERY', 1, 1, NULL, NULL, 1, 2.3, 'Ngồi duỗi thẳng hai chân phía trước.\nGiữ lưng thẳng, nghiêng người về trước từ hông.\nVới tay về phía mũi chân đến khi thấy căng nhẹ.\nGiữ 20-30 giây, thở đều, lặp lại 2-3 lần.', '/exercise-images/Seated_Floor_Hamstring_Stretch/0.jpg\n/exercise-images/Seated_Floor_Hamstring_Stretch/1.jpg', 'Có thể cong nhẹ đầu gối nếu còn căng.'),
(117, 'Giãn bắp chân vào tường', 'Giãn bắp chân với sự hỗ trợ của bức tường.', 3, 6, 1, 'LOW', 'NONE', 'ANY', 'calves', 'RECOVERY', 1, 1, NULL, NULL, 1, 2.3, 'Đứng đối diện tường, hai tay chống tường ngang ngực.\nBước một chân ra sau, giữ gót chân sát sàn.\nGập gối chân trước đến khi thấy căng bắp chân sau.\nGiữ 20-30 giây rồi đổi chân.', '/exercise-images/Calf_Stretch_Hands_Against_Wall/0.jpg\n/exercise-images/Calf_Stretch_Hands_Against_Wall/1.jpg', 'Giữ mũi chân hướng thẳng về phía tường.'),
(118, 'Giãn cơ gập hông quỳ', 'Giãn mặt trước hông, giúp ích khi ngồi nhiều.', 4, 8, 2, 'LOW', 'NONE', 'HOME', 'hips', 'RECOVERY', 2, 1, NULL, NULL, 1, 2.3, 'Quỳ một gối trên thảm, chân kia đặt phía trước, gối gập 90 độ.\nSiết nhẹ bụng, đẩy hông về trước đến khi thấy căng phía trước hông.\nGiữ 20-30 giây, thở đều.\nĐổi bên.', '/exercise-images/Kneeling_Hip_Flexor/0.jpg\n/exercise-images/Kneeling_Hip_Flexor/1.jpg', 'Không ưỡn lưng quá mức.'),
(119, 'Giãn ngực động', 'Mở rộng ngực và vai bằng chuyển động dang tay.', 3, 6, 1, 'LOW', 'NONE', 'ANY', 'chest', 'RECOVERY', 1, 1, NULL, NULL, 1, 2.3, 'Đứng thẳng, hai tay giơ ngang vai, khuỷu tay gập.\nMở hai tay ra sau, ưỡn ngực nhẹ.\nKhép tay về trước ngực.\nLặp lại chậm 10-15 lần.', '/exercise-images/Dynamic_Chest_Stretch/0.jpg\n/exercise-images/Dynamic_Chest_Stretch/1.jpg', 'Giữ cổ thả lỏng, không nhún vai.'),
(120, 'Nghiêng người đứng', 'Giãn hai bên thân người.', 3, 6, 1, 'LOW', 'NONE', 'ANY', 'obliques', 'RECOVERY', 1, 1, NULL, NULL, 1, 2.3, 'Đứng chân rộng bằng vai, một tay thả bên hông.\nĐưa tay còn lại lên cao rồi nghiêng người sang phía đối diện.\nGiữ 15-20 giây, thở đều.\nĐổi bên, lặp lại 2 lần mỗi bên.', '/exercise-images/Standing_Lateral_Stretch/0.jpg\n/exercise-images/Standing_Lateral_Stretch/1.jpg', 'Nghiêng sang bên, không xoay người ra trước.'),
(121, 'Cầu mông', 'Tập mông và đùi sau, an toàn cho người mới.', 6, 12, 2, 'MEDIUM', 'NONE', 'HOME', 'glutes', 'BUILD_MUSCLE', 2, 0, NULL, NULL, 1, 3.0, 'Nằm ngửa, gối co, bàn chân đặt sát sàn rộng bằng hông.\nĐạp gót, nâng hông lên đến khi vai - hông - gối thẳng hàng.\nSiết mông 1-2 giây ở trên cùng.\nHạ hông xuống chậm, lặp lại 10-15 lần.', '/exercise-images/Butt_Lift_Bridge/0.jpg\n/exercise-images/Butt_Lift_Bridge/1.jpg', '2-3 hiệp, không ưỡn lưng quá mức.'),
(122, 'Dead bug', 'Tập cơ lõi nhẹ nhàng khi nằm ngửa.', 5, 10, 2, 'LOW', 'NONE', 'HOME', 'core', 'BUILD_MUSCLE', 2, 1, NULL, NULL, 1, 3.0, 'Nằm ngửa, hai tay giơ thẳng lên trần, hai đầu gối gập 90 độ.\nGiữ lưng dưới áp sát sàn.\nHạ chậm tay phải và chân trái về phía sàn, rồi trở lại.\nĐổi bên, lặp lại 8-10 lần mỗi bên.', '/exercise-images/Dead_Bug/0.jpg\n/exercise-images/Dead_Bug/1.jpg', 'Nếu lưng dưới bị nhấc khỏi sàn, giảm biên độ.'),
(123, 'Gập bụng', 'Bài cơ bản cho cơ bụng.', 5, 10, 2, 'MEDIUM', 'NONE', 'HOME', 'abs', 'BUILD_MUSCLE', 3, 0, NULL, NULL, 1, 3.8, 'Nằm ngửa, gối co, hai tay đặt nhẹ sau đầu hoặc trước ngực.\nSiết bụng, nhấc vai và ngực lên khỏi sàn.\nGiữ 1 giây rồi hạ xuống chậm.\nLặp lại 12-15 lần, 2-3 hiệp.', '/exercise-images/Crunches/0.jpg\n/exercise-images/Crunches/1.jpg', 'Không kéo cổ bằng tay.'),
(124, 'Gập bụng chéo', 'Tập cơ bụng chéo.', 5, 10, 2, 'MEDIUM', 'NONE', 'HOME', 'obliques', 'BUILD_MUSCLE', 3, 0, NULL, NULL, 1, 3.8, 'Nằm ngửa, gối co, tay sau đầu.\nNhấc vai lên và xoay khuỷu tay phải về phía gối trái.\nHạ xuống rồi đổi bên.\nLặp lại 10-12 lần mỗi bên.', '/exercise-images/Cross-Body_Crunch/0.jpg\n/exercise-images/Cross-Body_Crunch/1.jpg', 'Xoay từ thân người, không kéo cổ.'),
(125, 'Plank nghiêng', 'Tập cơ lõi bên hông.', 5, 10, 3, 'MEDIUM', 'NONE', 'HOME', 'core', 'BUILD_MUSCLE', 3, 0, NULL, NULL, 1, 3.0, 'Nằm nghiêng, chống khuỷu tay dưới vai, hai chân duỗi.\nNâng hông lên để thân thẳng từ đầu đến chân.\nGiữ 15-30 giây, thở đều.\nHạ xuống, đổi bên.', '/exercise-images/Side_Bridge/0.jpg\n/exercise-images/Side_Bridge/1.jpg', 'Có thể gập gối để dễ hơn.'),
(126, 'Superman', 'Tập cơ lưng dưới và mông khi nằm sấp.', 5, 10, 2, 'LOW', 'NONE', 'HOME', 'lower_back', 'BUILD_MUSCLE', 2, 1, NULL, NULL, 1, 3.0, 'Nằm sấp, hai tay duỗi thẳng về phía trước.\nNhấc nhẹ tay, ngực và chân khỏi sàn cùng lúc.\nGiữ 2-3 giây, nhìn xuống sàn để cổ thẳng.\nHạ xuống chậm, lặp lại 8-10 lần.', '/exercise-images/Superman/0.jpg\n/exercise-images/Superman/1.jpg', 'Nhấc vừa phải, không ưỡn quá mức.'),
(127, 'Hít đất tựa bệ', 'Hít đất nhẹ hơn nhờ tay đặt trên bệ cao.', 8, 15, 2, 'MEDIUM', 'stable_surface', 'HOME', 'chest', 'BUILD_MUSCLE', 2, 0, NULL, NULL, 1, 3.5, 'Đặt hai tay lên mép bàn chắc hoặc bậc cao, rộng hơn vai.\nDuỗi thẳng chân ra sau, thân thẳng.\nHạ ngực về phía bệ, khuỷu tay chếch khoảng 45 độ.\nĐẩy người lên, lặp lại 8-12 lần.', '/exercise-images/Incline_Push-Up/0.jpg\n/exercise-images/Incline_Push-Up/1.jpg', 'Chọn bệ thật chắc và không trơn.'),
(128, 'Nâng chân sang bên', 'Tập cơ hông và đùi ngoài khi nằm nghiêng.', 5, 10, 1, 'LOW', 'NONE', 'HOME', 'hips', 'BUILD_MUSCLE', 2, 1, NULL, NULL, 1, 3.0, 'Nằm nghiêng, hai chân duỗi, đầu gối lên tay.\nNhấc chân trên lên cao, giữ bàn chân hướng thẳng.\nHạ chậm, lặp lại 12-15 lần.\nĐổi bên.', '/exercise-images/Side_Leg_Raises/0.jpg\n/exercise-images/Side_Leg_Raises/1.jpg', 'Giữ hông không xoay ra sau.'),
(129, 'Đạp mông ra sau', 'Tập mông bằng động tác đạp chân ra sau.', 5, 10, 2, 'LOW', 'NONE', 'HOME', 'glutes', 'BUILD_MUSCLE', 2, 1, NULL, NULL, 1, 3.0, 'Quỳ bốn điểm, lưng thẳng.\nĐạp một chân ra sau và lên cao, gối hơi gập.\nSiết mông ở điểm cao nhất.\nHạ chậm, lặp lại 12 lần rồi đổi chân.', '/exercise-images/Glute_Kickback/0.jpg\n/exercise-images/Glute_Kickback/1.jpg', 'Giữ thân người ổn định, không xoay hông.'),
(130, 'Bước lên bậc nâng gối', 'Bài sức mạnh chân kết hợp thăng bằng.', 8, 15, 3, 'MEDIUM', 'stable_step', 'HOME', 'legs', 'BUILD_MUSCLE', 3, 0, NULL, NULL, 1, 5.0, 'Đứng trước một bậc hoặc ghế chắc.\nBước chân phải lên bậc, đạp thẳng người và nâng gối trái lên cao.\nBước xuống chậm, đổi chân.\nLặp lại 10 lần mỗi bên.', '/exercise-images/Step-up_with_Knee_Raise/0.jpg\n/exercise-images/Step-up_with_Knee_Raise/1.jpg', 'Chọn bậc thấp và chắc, bám tường nếu cần.'),
(131, 'Nhảy sao', 'Cardio toàn thân cường độ cao.', 5, 10, 3, 'HIGH', 'NONE', 'ANY', 'full_body', 'LOSE_WEIGHT', 4, 0, NULL, NULL, 1, 8.0, 'Đứng thẳng, chân khép.\nHạ nhẹ gối rồi bật lên, dang tay và chân ra như ngôi sao.\nTiếp đất nhẹ bằng mũi chân, gối hơi gập.\nLàm 30 giây, nghỉ 30 giây, lặp lại.', '/exercise-images/Star_Jump/0.jpg\n/exercise-images/Star_Jump/1.jpg', 'Giảm xuống bước dang chân nếu đau gối.'),
(132, 'Đá gót chạm mông', 'Khởi động và cardio nhẹ đến vừa.', 5, 10, 2, 'MEDIUM', 'NONE', 'ANY', 'legs', 'LOSE_WEIGHT', 3, 0, NULL, NULL, 1, 7.0, 'Đứng thẳng, hai tay thả lỏng.\nĐá gót chân lên chạm mông, luân phiên hai chân.\nGiữ nhịp đều và thân người thẳng.\nLàm 30-40 giây, nghỉ ngắn, lặp lại.', '/exercise-images/Single_Leg_Butt_Kick/0.jpg\n/exercise-images/Single_Leg_Butt_Kick/1.jpg', 'Tiếp đất nhẹ để giảm áp lực lên khớp.'),
(133, 'Nhảy dây', 'Cardio hiệu quả, cần thể lực và dây nhảy.', 5, 15, 3, 'HIGH', 'jump_rope', 'ANY', 'full_body', 'ENDURANCE', 4, 0, NULL, NULL, 1, 10.0, 'Cầm dây hai tay, khuỷu tay sát thân.\nXoay dây bằng cổ tay, bật nhẹ bằng mũi chân khi dây đi qua.\nGiữ nhịp đều, thân người thẳng.\nLàm 1 phút, nghỉ 30 giây, lặp lại.', '/exercise-images/Rope_Jumping/0.jpg\n/exercise-images/Rope_Jumping/1.jpg', 'Nhảy thấp, tiếp đất bằng mũi chân, chọn mặt sàn phẳng.'),
(134, 'Đạp xe', 'Cardio ngoài trời cường độ vừa, nhẹ cho khớp gối.', 20, 60, 2, 'MEDIUM', 'bicycle', 'OUTDOOR', 'legs', 'ENDURANCE', 3, 0, NULL, NULL, 1, 5.5, 'Chỉnh yên sao cho gối gần duỗi thẳng khi đạp xuống.\nKhởi động 5 phút ở tốc độ nhẹ.\nGiữ nhịp đạp đều ở mức vẫn nói chuyện được.\nGiảm tốc dần trong 5 phút cuối.', '/exercise-images/Bicycling/0.jpg\n/exercise-images/Bicycling/1.jpg', 'Đội mũ bảo hiểm và tuân thủ luật giao thông.'),
(135, 'Nhảy xa tại chỗ', 'Bài sức bật cho người đã quen vận động.', 5, 10, 3, 'HIGH', 'NONE', 'OUTDOOR', 'legs', 'BUILD_MUSCLE', 4, 0, NULL, NULL, 1, 6.0, 'Đứng chân rộng bằng vai, tay ra sau.\nVung tay về trước và bật xa hết mức có thể.\nTiếp đất bằng hai chân, gối gập để hấp thụ lực.\nĐi bộ lại điểm xuất phát, nghỉ 30-45 giây giữa các lần.', '/exercise-images/Standing_Long_Jump/0.jpg\n/exercise-images/Standing_Long_Jump/1.jpg', 'Chọn mặt cỏ hoặc sàn không trơn.'),
(136, 'Inchworm', 'Vận động toàn thân, kết hợp giãn cơ và sức mạnh nhẹ.', 5, 10, 2, 'MEDIUM', 'NONE', 'HOME', 'full_body', 'STAY_ACTIVE', 2, 0, NULL, NULL, 1, 3.5, 'Đứng thẳng, cúi người chạm tay xuống sàn (gối có thể hơi gập).\nĐi tay ra phía trước đến tư thế plank.\nĐi chân tiến về phía tay, giữ chân thẳng nhất có thể.\nĐứng dậy và lặp lại 6-8 lần.', '/exercise-images/Inchworm/0.jpg\n/exercise-images/Inchworm/1.jpg', 'Đi chậm, giữ bụng siết.'),
(137, 'Hít đất tay rộng', 'Biến thể hít đất tập ngực nhiều hơn.', 8, 15, 3, 'MEDIUM', 'NONE', 'HOME', 'chest', 'BUILD_MUSCLE', 3, 0, NULL, NULL, 1, 4.0, 'Chống tay rộng hơn vai khoảng 1,5 lần.\nGiữ thân thẳng, siết bụng.\nHạ ngực xuống gần sàn rồi đẩy lên.\nLàm 3 hiệp x 6-10 lần.', '/exercise-images/Push-Up_Wide/0.jpg\n/exercise-images/Push-Up_Wide/1.jpg', 'Hạ gối xuống sàn để dễ hơn.'),
(138, 'Nhảy co gối', 'Bài sức bật cường độ cao.', 5, 10, 3, 'HIGH', 'NONE', 'HOME', 'legs', 'LOSE_WEIGHT', 4, 0, NULL, NULL, 1, 8.0, 'Đứng chân rộng bằng vai.\nBật thẳng lên cao, đưa hai gối về phía ngực.\nTiếp đất nhẹ, gối hơi gập.\nLàm 20-30 giây, nghỉ 30-40 giây, lặp lại.', '/exercise-images/Knee_Tuck_Jump/0.jpg\n/exercise-images/Knee_Tuck_Jump/1.jpg', 'Chỉ làm trên sàn phẳng, tránh nếu đau gối.');
